# -*- coding: utf-8 -*-
"""Часть 2: сила руки и синтез, силы, прочность, уточнённый расчёт, МКЭ, прототип, допущения."""


def build(D, G, R):
    # ------------------------------------------------------------------ 8
    D.h1("8. Сила руки и выбор размеров (синтез)")
    D.h2("8.1. Как рука связана с крышкой")
    D.box("Термин", "**Работа** — сила, умноженная на путь вдоль неё; измеряется в джоулях (Дж). **Принцип возможных перемещений:** если трения нет, работа руки на маленьком "
          "перемещении равна работе, которую получает крышка.")
    D.p("Рука опускает конец рукояти по вертикали на $L·\\cos φ·dφ$, ползун при этом проходит $\\frac{e}{\\cos^{2} φ}·dφ$. Приравниваем работы:")
    D.f("P·L·\\cos φ=F·\\frac{e}{\\cos^{2} φ}")
    D.f("P=\\frac{F·e}{L·\\cos^{3} φ},\\quad L=\\frac{F·e}{P·\\cos^{3} φ}")
    D.where([["$P$", "сила руки на конце рукояти, направлена вниз", "до 112,8 Н"], ["$F$", "сила сопротивления крышки", "до 1974 Н"],
             ["$e$", "расстояние от оси O до линии ползуна", "12,53 мм"], ["$L$", "длина рукояти", "500 мм"],
             ["$\\cos^{3} φ$", "косинус в кубе; учитывает, как меняются плечи при повороте", "при 41,63°: 0,417"]])
    D.box("У нас", "Выигрыш в силе $\\frac{F}{P}=\\frac{L·\\cos^{3} φ}{e}$: при касании крышки 16,45 раза, в конце — 31,32 раза. В момент начала обжима: "
          "$P=\\frac{1880·12,53}{500·0,417}=112,8$ Н, то есть меньше 120 Н.")
    D.h2("8.2. Что такое синтез и оптимизация")
    D.box("Термин", "**Метрический синтез** — подбор размеров механизма под требования. **Оптимизация** — поиск наилучшего варианта. **Критерий** (целевая функция) — число, по которому "
          "сравнивают варианты. **Ограничение** — условие, которое нарушать нельзя.")
    D.p("Мы хотим, чтобы механизм был маленьким, а рукоять поворачивалась на небольшой угол. Отсюда два критерия — чем меньше, тем лучше:")
    D.ul(["**площадь треугольника** O–$B_{н}$–$B_{к}$, который заметает кулиса у камня, — мера размера механизма;",
          "**угловой ход** $ψ=φ_{н}-φ_{к}$ — насколько надо повернуть рукоять."])
    D.img(R("схема_синтез.png"), 8.2, "Треугольник, площадь которого уменьшаем, и угол ψ", maxh=9.5)
    D.f("A=\\frac{1}{2}·e·S,\\quad e=\\frac{S}{\\tg \\p{φ_{к}+ψ}-\\tg φ_{к}}")
    D.where([["$A$", "площадь треугольника: половина основания ($S$) на высоту ($e$)", "100,2 мм²"], ["$S$", "ход ползуна (основание треугольника)", "16 мм"],
             ["$φ_{к}+ψ$", "это и есть начальный угол $φ_{н}$", "59,47°"]])
    D.p("**Ограничения:** рукоять $L≤500$ мм, расстояние $e≥10$ мм (чтобы детали поместились), угол давления не больше 60°, сила руки $P≤120$ Н.")
    D.h2("8.3. Почему нельзя получить всё сразу")
    D.p("Критерии спорят: меньше площадь — больше угол, и наоборот. Наименьшая площадь 80 мм² получается при угле 52,5°, а наименьший угол 29,33° — при большой площади.")
    D.img(R("синтез_уступки.png"), 13.5, "Слева — площадь в зависимости от угла, справа — относительные уступки; точка K — наш выбор")
    D.box("Термин", "**Компромисс по равным относительным уступкам:** выбираем вариант, в котором от идеала по каждому критерию отступили на одинаковый процент.")
    D.f("δ_{A}=\\frac{A}{A^{*}}-1=\\frac{100,2}{80,0}-1=25,3\\t{ %},\\quad δ_{ψ}=\\frac{ψ}{ψ^{*}}-1=\\frac{36,75}{29,33}-1=25,3\\t{ %}")
    D.where([["$A^{*}$, $ψ^{*}$", "лучшие возможные значения каждого критерия по отдельности", "80,0 мм² и 29,33°"], ["$δ_{A}$, $δ_{ψ}$", "на сколько процентов наш вариант хуже идеала", "по 25,3 %"]])
    D.box("У нас", "$ψ=36,75°$, $e=12,53$ мм, кулиса ходит от $φ_{н}=59,47°$ до $φ_{к}=22,72°$. Площадь 100,2 мм².")
    D.h2("8.4. Длина рукояти")
    D.p("Для каждого положения считаем, какая длина нужна, чтобы хватило 120 Н. Самая большая потребовалась в начале обжима:")
    D.f("L_{треб}=\\frac{F_{ук}·e}{P_{доп}·\\cos^{3} φ}=470,1\\t{ мм при }φ_{у}=41,63°")
    D.img(R("длина_рукояти.png"), 11.5, "Требуемая длина рукояти по ходу и принятые 500 мм")
    D.p("Короче 470,1 мм нельзя: руке придётся давить больше 120 Н. Берём ближайшее большее стандартное — **500 мм**, тогда $P_{max}=120·\\frac{470,1}{500}=112,8$ Н.")
    D.box("Термин", "**Ряды нормальных размеров** (ГОСТ 6636-69: Ra5, Ra10, Ra20, Ra40) — список «красивых» чисел, которыми договорились пользоваться. Ra5 — самый короткий и "
          "предпочтительный, Ra40 — самый подробный. Поэтому ход 15 мм из задания (есть только в Ra40) заменили на 16 мм, а 470 — на 500 мм.")

    # ------------------------------------------------------------------ 9
    D.h1("9. Силы внутри механизма: первичный силовой расчёт")
    D.box("Зачем это нужно", "Чтобы знать, какой толщины делать каждую деталь, надо знать, с какой силой на неё давят соседние.")
    D.h2("9.1. Как находят силы")
    D.box("Термин", "**Реакция** — сила, с которой соседняя деталь или опора отвечает на нажатие. **Третий закон Ньютона:** с какой силой первая деталь давит на вторую, "
          "с такой же вторая давит на первую, только в обратную сторону. **Расчётная схема** — одна деталь, нарисованная отдельно, со всеми силами на ней.")
    D.p("Приём называется **освобождением от связей**: мысленно вынимаем деталь из механизма, а вместо соседей рисуем их силы. Обозначение $R_{12}$ читается «сила, с которой звено 2 действует на звено 1» "
        "(по схемам РПЗ: $R_{12}$ приложена к кулисе 1 со стороны камня 2).")
    D.p("**Условие равновесия.** Если деталь не ускоряется, все силы на ней уравновешены. На плоскости это три уравнения:")
    D.f("∑F_{x}=0,\\quad ∑F_{y}=0,\\quad ∑M_{M}=0")
    D.where([["$∑F_{x}$", "сумма всех сил по горизонтали: ничто не сдвигает вбок", "0"], ["$∑F_{y}$", "сумма всех сил по вертикали", "0"],
             ["$∑M_{M}$", "сумма всех моментов вокруг точки M: ничто не поворачивает", "0"]])
    D.p("Звеньев три, уравнений по три на каждое — всего 9 уравнений и 9 неизвестных. Решение есть и оно единственное. Массы и трение пока не учитываем.")
    D.h2("9.2. Три детали и их уравнения")
    D.img(R("схемы_первичный.png"), 14.0, "Расчётные схемы: кулиса, камень, ползун", maxh=12)
    D.p("**Кулиса (звено 1).** На неё действуют ось O ($R_{10}$), камень ($R_{12}^{N}$, перпендикулярно кулисе) и рука ($P$):")
    D.f("R_{10}^{x}+R_{12}^{N}·\\cos \\p{φ+90°}=0", "R_{10}^{y}+R_{12}^{N}·\\sin \\p{φ+90°}-P=0")
    D.p("Угол $φ+90°$ — направление, перпендикулярное кулисе: без трения камень может давить только так. Буква $N$ вверху — «нормальная», то есть перпендикулярная.")
    D.p("Уравнение моментов кулисы: каждая сила умножается на своё плечо до точки M, $a(φ)$ — плечо силы камня, $M_{12}$ — возможный момент в паре:")
    D.f("R_{10}^{x}·y_{M}+R_{10}^{y}·x_{M}+R_{12}^{N}·a+M_{12}-P·X_{K}=0")
    D.p("**Камень (звено 2)** и **ползун (звено 3)** — так же, по три уравнения. Для ползуна главные:")
    D.f("-R_{23}^{x}+R_{30}^{N}=0,\\quad -R_{23}^{y}+F_{ук}=0")
    D.where([["$R_{23}$", "сила в пальце D между камнем и ползуном, по осям $x$ и $y$", "−1671 и 1880 Н"], ["$R_{30}^{N}$", "сила направляющей: не даёт ползуну уйти вбок", "1671 Н (по модулю)"],
             ["$M_{12}$, $M_{30}$", "моменты в поступательных парах; в нашей схеме вышли нулевыми", "0"], ["$x_{M}$, $y_{M}$", "расстояния от точки M до оси O, конца рукояти и т. д.; их берут из чертежа", "—"]])
    D.h2("9.3. Матрица — просто таблица чисел")
    D.box("Простыми словами", "Девять уравнений записали таблицей: строка — уравнение, столбец — неизвестное, в клетке — множитель. Это **матрица** $A$. Запись $A·X=B$ означает «таблица, умноженная "
          "на столбец неизвестных $X$, равна столбцу известных $B$». Решает компьютер, для 40 001 положения кулисы.")
    D.p("Ответ можно получить и формулами — он совпал с компьютерным:")
    D.f("R_{12}^{N}=\\frac{F_{ук}}{\\cos φ},\\quad R_{30}^{N}=-F_{ук}·\\tg φ,\\quad R_{10}^{x}=F_{ук}·\\tg φ,\\quad R_{10}^{y}=P-F_{ук}")
    D.img(G("04_разложение.png"), 8.5, "Почему так: сила камня направлена косо. Вертикальная часть — полезная, горизонтальная — боковая")
    D.p("Проверка для $φ_{у}=41,63°$, где $F=1880$ Н: $R_{12}=\\frac{1880}{0,747}=2515$ Н, боковая сила $1880·0,889=1671$ Н.")
    D.table(["Момент", "Угол", "Крышка, Н", "Рука, Н", "Ось O, Н", "Камень, Н", "Направляющая, Н"], [
        ["касание крышки", "41,91°", "0", "0", "0", "0", "0"], ["начало обжима", "41,63°", "1880", "**112,8**", "2432", "2515", "1671"],
        ["середина", "30,00°", "1942", "74,9", "2178", "2242", "1121"], ["конец", "22,72°", "1974", "63,0", "2082", "2140", "826"]],
        [3.3, 1.8, 2.1, 2.0, 2.2, 2.4, 3.0], size=10, caption="Силы в характерных положениях")
    D.box("У нас", "Рука устаёт сильнее всего в начале обжима (112,8 Н), хотя сопротивление крышки больше в конце (1974 Н). Причина: к концу кулиса ложится и выигрыш в силе растёт почти вдвое.")
    D.box("Частая ошибка", "Думать, что самое опасное положение — там, где наибольшая сила крышки. Для кулисы, камня, пальца и оси это начало обжима ($φ_{у}$), и только для штока — конец хода ($φ_{к}$).")

    # ------------------------------------------------------------------ 10
    D.h1("10. Основы прочности")
    D.h2("10.1. Какие бывают нагрузки")
    D.img(G("06_деформации.png"), 15.0, "Пять видов нагрузки, которые встречаются в наших деталях")
    D.table(["Вид", "Что происходит", "Где у нас"], [["сжатие", "деталь укорачивается", "шток"], ["изгиб", "деталь гнётся", "кулиса"], ["срез", "одна часть сдвигается относительно другой", "ось O, палец D, перемычки у отверстий"],
                                                  ["смятие", "поверхность проминается под нажимом", "стенки отверстий, рёбра кулисы"], ["потеря устойчивости", "тонкий стержень внезапно выгибается", "шток"]], [4.0, 6.8, 6.0], size=10)
    D.h2("10.2. Что умеет металл")
    D.img(G("07_диаграмма.png"), 11.5, "Диаграмма растяжения стали: сначала упруго, потом течёт, потом рвётся")
    D.f("σ=E·ε_{отн}")
    D.where([["$E$", "модуль упругости (Юнга): насколько материал жёсткий", "сталь 200 000 МПа"], ["$ε_{отн}$", "относительное удлинение: на какую долю удлинилась деталь", "—"], ["$σ$", "напряжение, МПа", "—"]])
    D.p("Это **закон Гука**: пока напряжение невелико, удлинение ему пропорционально, как у пружины.")
    D.box("Термин", "**Предел текучести** $σ_{т}$ — дальше деталь согнётся насовсем. **Предел прочности** $σ_{в}$ — дальше разрушится. **Допускаемое напряжение** $[σ]$ — сколько разрешаем мы.")
    D.f("\\br{σ}=\\frac{σ_{т}}{n}")
    D.where([["$n$", "коэффициент запаса: во сколько раз держимся ниже опасного", "2,5"], ["$σ_{т}$", "предел текучести", "Ст3сп: 245 МПа"], ["$[σ]$", "допускаемое напряжение", "245/2,5 = 98 МПа"]])
    D.table(["Сталь", "Что за обозначение", "$σ_{т}$, МПа", "$[σ]$, МПа", "Где"], [
        ["Ст3сп", "обычная углеродистая; «сп» — спокойная (без пузырей газа)", "245", "98", "кулиса, ползун, стойка"],
        ["45", "0,45 % углерода, качественная", "355", "142", "ось O, камень, направляющая"],
        ["40Х", "0,40 % углерода и около 1 % хрома, закалённая", "785", "314", "палец D"]], [2.0, 6.4, 2.3, 2.1, 4.0], size=10)
    D.p("**АБС** — пластик кожуха: кожух силу не держит. **ЭЖК** — жесть самой крышки.")
    D.h2("10.3. Изгиб")
    D.img(G("08_изгиб.png"), 12.0, "При изгибе одна сторона сжата, другая растянута, посередине ничего")
    D.f("σ=\\frac{M}{W}")
    D.where([["$M$", "изгибающий момент в этом месте, Н·мм", "40 750 Н·мм"], ["$W$", "момент сопротивления: насколько форма сечения мешает изгибу, мм³", "432 мм³"]])
    D.f("\\t{прямоугольник: }W=\\frac{b·h^{2}}{6},\\quad \\t{круг: }W=\\frac{π·d^{3}}{32}")
    D.where([["$b$", "толщина полосы (ширина сечения)", "8 мм"], ["$h$", "высота сечения в сторону изгиба; входит в квадрате — самая важная", "18 мм"], ["$d$", "диаметр круга", "—"]])
    D.box("Простыми словами", "Линейку легко согнуть плашмя и почти невозможно на ребро: высота во втором случае больше, а она в квадрате. Поэтому полоса кулисы стоит на ребро.")
    D.h2("10.4. Срез и смятие")
    D.f("τ_{ср}=\\frac{4·R}{π·d^{2}}≤\\br{τ_{ср}},\\quad σ_{см}=\\frac{R}{d·l}≤\\br{σ_{см}},\\quad τ=\\frac{R}{2·c·s}≤\\br{τ}")
    D.where([["$τ_{ср}$", "напряжение среза в пальце: сила, делённая на площадь круга", "31,0 и 32,0 МПа"], ["$σ_{см}$", "напряжение смятия: сила на площадь «диаметр × длина отверстия»", "12,2 и 15,7 МПа"],
             ["$τ$", "срез перемычки — полоски металла между отверстием и краем", "38,0 и 11,2 МПа"], ["$R$", "сила в соединении", "2432 и 2515 Н"],
             ["$d$, $l$", "диаметр пальца и длина отверстия", "10 мм; 16 мм у ползуна"], ["$c$, $s$", "ширина и толщина перемычки; двойка — потому что перемычек две", "—"]])
    D.h2("10.5. Устойчивость")
    D.img(G("09_устойчивость.png"), 8.5, "Длинный тонкий стержень выгибается раньше, чем сомнётся")
    D.box("Простыми словами", "Нажмите сверху на тонкую пластиковую линейку, поставленную вертикально: она не сломается, а резко выгнется вбок. Это и есть потеря устойчивости.")
    D.f("λ=\\frac{μ·l}{i},\\quad i=\\sqrt{\\frac{I_{min}}{A}}=\\frac{d}{4}")
    D.where([["$λ$", "гибкость: чем больше, тем легче выгнуть", "60"], ["$μ$", "коэффициент закрепления: 2 — один конец зажат, другой свободен (худший случай)", "2"], ["$l$", "длина стержня", "60 мм"],
             ["$i$", "радиус инерции сечения — мера его «толщины»", "8/4 = 2 мм"], ["$I_{min}$", "момент инерции сечения: как материал удалён от середины; для круга $\\frac{π·d^{4}}{64}$", "201 мм⁴"]])
    D.f("λ≥100:\\quad F_{кр}=\\frac{π^{2}·E·I_{min}}{\\p{μ·l}^{2}}\\quad \\t{(Эйлер)}", "λ<100:\\quad σ_{кр}=a-b·λ≤σ_{т},\\quad F_{кр}=σ_{кр}·A\\quad \\t{(Ясинский)}", "n_{у}=\\frac{F_{кр}}{F_{ук}}≥3")
    D.where([["$F_{кр}$", "критическая сила: при ней стержень выгнется", "12 144 Н"], ["$a$, $b$", "числа из таблицы для стали Ст3 (проверены опытом)", "310 и 1,14 МПа"], ["$σ_{кр}$", "критическое напряжение: 310 − 1,14·60", "≈ 242 МПа"], ["$n_{у}$", "запас устойчивости", "6,15"]])
    D.p("Почему две формулы: формула Эйлера верна для тонких стержней. Для более толстых материал начинает течь раньше, и работает опытная формула Ясинского. Граница для Ст3 — $λ=100$, у нас 60.")

    # ------------------------------------------------------------------ 11
    D.h1("11. Подбираем толщины наших деталей")
    D.h2("11.1. Кулиса: эпюры")
    D.box("Термин", "**Внутренние силовые факторы** — силы, которые держат две половины детали вместе, если её мысленно разрезать: продольная сила $N$ (вдоль), поперечная $Q$ (поперёк) и изгибающий момент $M$. "
          "**Эпюра** — график, показывающий, как они меняются по длине.")
    D.f("N=-P·\\sin φ,\\quad Q_{O-D}=P·\\cos φ-\\frac{F_{ук}}{\\cos φ},\\quad Q_{D-K}=P·\\cos φ,\\quad \\abs{M_{D}}=P·\\p{L·\\cos φ-e}")
    D.where([["$N$", "продольная сила; минус — сжатие", "−75,0 Н"], ["$Q_{O-D}$", "поперечная сила на участке от оси до камня", "−2430,5 Н"], ["$Q_{D-K}$", "поперечная сила от камня до руки", "+84,3 Н"], ["$M_{D}$", "наибольший изгибающий момент — под камнем", "40,75 Н·м"]])
    D.img(R("эпюры_фи_у.png"), 14.5, "Эпюры кулисы в самом опасном положении. Опасное сечение — D, под камнем")
    D.p("Читать так: чем дальше заштрихованная область от линии кулисы, тем больше величина в этом месте. Момент у конца K равен нулю, у камня — наибольший.")
    D.h2("11.2. Кулиса: размер полосы")
    D.f("σ=\\frac{\\abs{N}}{A}+\\frac{\\abs{M_{D}}}{W}=\\frac{75}{144}+\\frac{40750}{432}=94,8\\t{ МПа}≤98\\t{ МПа}")
    D.where([["$A$", "площадь сечения 8 · 18", "144 мм²"], ["$W$", "момент сопротивления $8·18^{2}/6$", "432 мм³"], ["$\\abs{N}/A$", "вклад сжатия — почти ничего", "0,5 МПа"], ["$\\abs{M_{D}}/W$", "вклад изгиба — почти всё", "94,3 МПа"]])
    D.p("Расчётом получили нужную высоту 17,71 мм, взяли 18 мм. Срез проверяют по **формуле Журавского** — при изгибе наибольшее касательное напряжение в прямоугольнике в полтора раза больше среднего:")
    D.f("τ_{max}=\\frac{1,5·\\abs{Q}}{b·h}=\\frac{1,5·2430,5}{8·18}=25,3\\t{ МПа}≤49\\t{ МПа}")
    D.p("**Прогиб** — на сколько опустится конец рукояти под нагрузкой: $f_{K}=4,0$ мм. Почему не взяли более прочную сталь 40Х: полоса вышла бы тоньше и легче, но гнулась бы на 23,4 мм — неприятно руке.")
    D.box("Простыми словами", "Прочность и жёсткость — разные вещи. Прочная деталь не сломается, жёсткая — не прогнётся. Все стали по жёсткости почти одинаковы.")
    D.h2("11.3. Шток")
    D.f("σ=\\frac{F_{ук}}{A}=\\frac{1974}{50,3}=39,3\\t{ МПа}≤98\\t{ МПа},\\quad n_{у}=\\frac{12144}{1974}=6,15≥3")
    D.p("Шток держит сжатие с большим запасом. Диаметр 8 мм выбран из-за устойчивости при перегрузке: если крышку обжимать с силой 3758 Н, запас остаётся 3,23.")
    D.h2("11.4. Ось, палец и отверстия")
    D.f("d_{O}≥\\sqrt{\\frac{4·2432}{π·50}}=7,87\\t{ мм},\\quad d_{D}≥\\sqrt{\\frac{4·2515}{π·50}}=8,00\\t{ мм}")
    D.p("Это формула среза, из которой выразили диаметр; 50 МПа — допускаемое напряжение. Взяли Ø10 мм.")
    D.box("Термин", "**Ступица** — утолщение вокруг отверстия. У кулисы она нужна именно потому, что без неё отверстие не проходило по смятию (30,4 > 24). **Запрессовка** — деталь вставлена с усилием и держится сама.")
    D.table(["Что проверяли", "Вид", "Вышло, МПа", "Можно, МПа"], [["ось O Ø10, сталь 45", "срез", "31,0", "50"], ["отверстие кулисы без утолщения", "смятие", "**30,4**", "24 — не проходит"],
                                                                 ["отверстие кулисы со ступицей", "смятие", "12,2", "24"], ["перемычка кулисы у оси", "срез", "38,0", "49"], ["отверстие стойки (ось запрессована)", "смятие", "20,3", "65"],
                                                                 ["палец D Ø10, сталь 40Х", "срез", "32,0", "50"], ["отверстие ползуна", "смятие", "15,7", "24"], ["перемычка ползуна", "срез", "11,2", "49"],
                                                                 ["камень на ребре кулисы", "смятие", "15,7", "24"], ["ползун о направляющую (стенки)", "смятие", "2,6", "24"]], [7.4, 2.6, 3.2, 3.6], size=10)

    # ------------------------------------------------------------------ 12
    D.h1("12. Уточнённый расчёт: учитываем массу")
    D.box("Зачем это нужно", "В первом расчёте детали считались невесомыми: их толщины ещё не знали. Теперь знаем, можно взвесить и проверить, не изменится ли ответ.")
    D.h2("12.1. Инерция и принцип Д'Аламбера")
    D.box("Простыми словами", "Когда автобус трогается, вас прижимает к спинке. Никто не толкает — это тело «не хочет» менять скорость. Это явление называется инерцией.")
    D.box("Термин", "**Кинетостатика (принцип Д'Аламбера)** — приём: к движущемуся с ускорением телу добавляем воображаемую **силу инерции** $Φ$, направленную против ускорения, и после этого пишем обычные уравнения равновесия.")
    D.f("Φ_{1τ}=m_{1}·ε·z_{S},\\quad Φ_{1n}=m_{1}·ω^{2}·z_{S},\\quad M_{Φ1}=J_{S}·ε,\\quad Φ_{3}=-m_{3}·a_{D}")
    D.where([["$Φ_{1τ}$, $Φ_{1n}$", "силы инерции кулисы: поперёк и вдоль неё", "до 0,452 и 0,277 Н"], ["$M_{Φ1}$", "момент сил инерции кулисы", "до 0,0415 Н·м"], ["$Φ_{3}$", "сила инерции ползуна", "до 0,042 Н"],
             ["$m_{1}$, $m_{3}$", "массы кулисы и ползуна", "0,585 и 0,270 кг"], ["$z_{S}$", "расстояние от оси O до центра масс кулисы", "241,6 мм"], ["$J_{S}$", "момент инерции относительно центра масс", "0,0130 кг·м²"]])
    D.box("Термин", "**Центр масс** — точка, за которую тело можно подвесить и оно не повернётся. **Момент инерции** $J$ — «масса для вращения»: чем дальше вещество от оси, тем труднее раскрутить.")
    D.f("J_{O}=J_{S}+m_{1}·z_{S}^{2}=0,0130+0,585·0,2416^{2}=0,0471\\t{ кг·м}^{2}")
    D.p("Это **теорема Гюйгенса — Штейнера**: момент инерции вокруг другой оси равен моменту вокруг центра масс плюс масса на квадрат расстояния между осями.")
    D.h2("12.2. Новая сила руки")
    D.f("F_{пр}=F_{ук}-G_{3}+Φ_{3}", "P=\\frac{\\frac{F_{пр}·e}{\\cos^{2} φ}-G_{1}·z_{S}·\\cos φ+J_{O}·ε}{L·\\cos φ}")
    D.where([["$F_{пр}$", "приведённая сила: крышка минус вес ползуна (он помогает) плюс его инерция", "—"], ["$G_{1}$, $G_{3}$", "вес кулисы и ползуна", "5,74 и 2,65 Н"], ["$J_{O}·ε$", "момент на разгон кулисы", "—"]])
    D.box("У нас", "$P_{max}=109,9$ Н вместо 112,8 — меньше на 2,6 %: вес рукояти помогает. Остальные силы изменились меньше чем на 1 %, поэтому толщины оставили.")
    D.p("Почему инерция почти ничего не значит: энергия движения кулисы $\\frac{J_{O}·ω^{2}}{2}=\\frac{0,0471·1,4^{2}}{2}=0,046$ Дж, а работа на обжим крышки — 11,5 Дж, то есть в 250 раз больше.")
    D.img(R("сила_руки_t.png"), 11.0, "Сила руки по времени: первичный и уточнённый расчёты, предел 120 Н")

    # ------------------------------------------------------------------ 13
    D.h1("13. 3D-модели и метод конечных элементов")
    D.h2("13.1. КОМПАС-3D")
    D.p("КОМПАС — программа, где деталь строят объёмной: рисуют контур (**эскиз**) и выдавливают его, вырезают отверстия, скругляют рёбра (**скругление**) или срезают их под углом (**фаска**). Из деталей собирают **сборку**, "
        "связывая их **сопряжениями** (например, «отверстие на оси»).")
    D.img(R("детали.png"), 15.0, "Детали укупоривателя")
    D.p("**Резьба М10 × 1,5:** метрическая, наружный диаметр 10 мм, шаг (расстояние между витками) 1,5 мм. **Ø** — знак диаметра, **R3** — скругление радиусом 3 мм.")
    D.h2("13.2. Метод конечных элементов (МКЭ)")
    D.img(G("11_мкэ.png"), 11.0, "Деталь делят на тысячи маленьких кусочков")
    D.box("Простыми словами", "Формулы из главы 10 годятся для простых форм — брусков и кругов. Настоящая деталь сложнее. Её делят на тысячи крошечных кусочков, для каждого пишут простые уравнения, а компьютер решает их все вместе и раскрашивает деталь по напряжению.")
    D.box("Термин", "**Сетка** — набор этих кусочков (у нас десятиузловые тетраэдры — маленькие пирамидки). **APM FEM** — программа МКЭ внутри КОМПАСа. Чтобы запустить расчёт, задают **закрепление** (где деталь держат), **нагрузку** (где и с какой силой давят) и материал.")
    D.p("В каждой точке металл может одновременно и сжиматься, и сдвигаться. Чтобы сравнить это с одним числом $[σ]$, всё сводят в **эквивалентное напряжение по Мизесу** (энергетическая теория прочности). Для простого случая, когда есть одно $σ$ и одно $τ$:")
    D.f("σ_{экв}=\\sqrt{σ^{2}+3·τ^{2}}≤\\br{σ}")
    D.where([["$σ_{экв}$", "эквивалентное напряжение: так же опасно, как всё вместе; в APM подписано SVM", "ниже в таблице"], ["$σ$, $τ$", "нормальное и касательное напряжения в точке", "—"]])
    D.h2("13.3. Что показал МКЭ и что изменили")
    D.table(["Деталь", "$σ_{экв}$ до → после, МПа", "Можно, МПа", "Масса, г", "Что сделали"], [
        ["Кулиса", "92,6 → 92,6", "98", "577,6 → 449,7", "вырезали 9 пазов по середине, где напряжения малы"],
        ["Ползун", "95,9 → 49,0", "98", "418,7 → 320,8", "скругления R3, головка стала колоколом"],
        ["Камень", "646 → 100", "142", "30,7 → 34,6", "закрыли обойму задней стенкой, скругления R1,5"],
        ["Направляющая (со стенками)", "920 → 136,2", "142", "402,3 → 597,2", "толстая стенка 12 мм, скругления R10 и R14"],
        ["Направляющая без стенок (для печати)", "920 → 60,7", "142", "402,3 → 389,9", "приложена только сила 1671 Н, без момента (глава 14)"],
        ["Палец D", "192", "314", "18,7", "взяли сталь 40Х"]], [3.4, 3.3, 2.0, 3.0, 5.1], size=10)
    D.img(R("РПЗ_камень"), 14.0, "Камень до и после: наибольшее напряжение снизилось с 646 до 100 МПа (у каждой картинки своя шкала цвета)")
    D.box("Термин", "**Концентрация напряжений** — скачок напряжения у острого угла, выреза или отверстия. Лечится скруглением: у ползуна острый угол давал 95,9 МПа, скругление R3 снизило до 49,0.")
    D.box("Простыми словами", "Почему пазы в кулисе её не ослабили: при изгибе середина полосы почти не нагружена (рисунок про изгиб в главе 10), металл оттуда можно убрать.")

    # ------------------------------------------------------------------ 14
    D.h1("14. Прототип и направляющая: зачем нужны стенки")
    D.h2("14.1. Печать")
    D.box("Термин", "**Прототип** — первый экземпляр, чтобы проверить, что всё собирается. **FDM-печать** — 3D-принтер укладывает расплавленный пластик слой за слоем. **STL** — файл с формой детали из треугольников для принтера.")
    D.p("Для печати детали немного изменили, расчёты при этом остались прежними: ползун разделён на две части (головка приклеивается снизу), у направляющей появилась полка с отверстием Ø8,6 под шток Ø8. **Зазор** 0,3 мм на сторону нужен, чтобы шток ходил свободно.")
    D.h2("14.2. Кто держит ползун сбоку")
    D.p("Из главы 9: камень толкает палец D вбок с силой 1671 Н. Её должна держать направляющая. Во всех расчётах принято, что она держит **на уровне пальца D**, то есть боковыми стенками.")
    D.img(G("10_стенки.png"), 12.5, "Слева — стенки рядом с силой, справа — только полка внизу")
    D.p("Если оставить только полку, опора окажется на 57,9 мм ниже силы, и появится изгиб:")
    D.f("M=R_{30}·h=1671·57,9=96\\,700\\t{ Н·мм},\\quad σ=\\frac{M}{W}=\\frac{96700}{50,3}≈1920\\t{ МПа}".replace("\\,", " "))
    D.where([["$R_{30}$", "боковая сила", "1671 Н"], ["$h$", "расстояние от пальца D до середины полки (в начале обжима)", "57,9 мм"], ["$W$", "момент сопротивления круга Ø8: $\\frac{π·8^{3}}{32}$", "50,3 мм³"], ["$[σ]$", "допускаемое для Ст3сп", "98 МПа"]])
    D.box("У нас", "Напечатанная направляющая без стенок — макет: показывает сборку и движение, но обжимать крышку ею нельзя. Все расчёты сделаны для направляющей со стенками. В основной версии РПЗ на рисунках стоит направляющая без стенок — это надо уметь объяснить, если спросят.")

    # ------------------------------------------------------------------ 15
    D.h1("15. Что мы упростили")
    D.p("Любой расчёт — модель. Честно перечислить допущения важнее, чем сделать вид, что их нет.")
    D.table(["Допущение", "Почему так можно", "Чем грозит"], [
        ["Трения нет", "первый расчёт всегда делают без него, реакции выходят простыми", "сила руки на деле больше. Пример: если в направляющей коэффициент трения 0,1, то $P≈\\frac{(1880+0,1·1671)·12,53}{500·0,417}≈123$ Н — чуть больше 120. Запас 6 % невелик, нужна смазка"],
        ["Крышка — худший случай ($n=2,0$, 28,6 мм)", "лучше взять с запасом", "на деле сила, скорее всего, меньше"],
        ["Детали жёсткие", "прогибы малы по сравнению с размерами", "кулиса прогибается на 4 мм на конце — рука это почувствует"],
        ["Камень невесомый", "он весит 35 г", "влияние ничтожно"],
        ["Нагрузка спокойная", "движение медленное, инерция мала", "усталость и удары не проверяли (глава 16)"]], [4.2, 5.0, 7.6], size=10)
